"""Telegram labels and callback data generated by the application."""

NAVIGATION = {
    "nav:now": "/now",
    "nav:guest": "/guest",
    "nav:brief": "/brief",
    "nav:details": "/brief_more",
    "nav:help": "/help",
}


# Notices the coordinator needs to see acknowledged. Each gets an Acknowledge button.
ACK_TOPICS = {"coordinator_message", "timeline_updated"}
ACK_PROMPT = "Tap Acknowledge, or reply \u201cok\u201d, so the coordinator knows you saw this."


def notice_markup(topic: str, notification_id: str) -> dict | None:
    if topic not in ACK_TOPICS:
        return None
    return {"inline_keyboard": [[{"text": "Acknowledge", "callback_data": f"ack:{notification_id}"}]]}


def approval_markup(approval_id: str, *, blocked: bool) -> dict:
    """Buttons for the coordinator on an approval request. A blocked change can only be rejected."""
    buttons = [] if blocked else [{"text": "Approve", "callback_data": f"approve:{approval_id}"}]
    buttons.append({"text": "Reject", "callback_data": f"reject:{approval_id}"})
    return {"inline_keyboard": [buttons]}


# What the button under a draft does, in plain words.
DRAFT_BUTTONS = {"propose_delay": "Send to coordinator", "change_item": "Send change", "report_incident": "Send",
                 "arrival": "Record arrival", "withdraw_report": "Withdraw it", "broadcast": "Send message",
                 "set_deputy_enabled": "Confirm switch"}


def reply_markup(*, coordinator: bool, guest_lookup: bool, draft_id: str | None,
                 app_url: str, draft_type: str | None = None) -> dict:
    def button(label: str, action: str) -> dict:
        return {"text": label, "callback_data": action}

    keyboard = []
    if draft_id:
        keyboard.append([button(DRAFT_BUTTONS.get(draft_type, "Confirm"), f"confirm:{draft_id}")])
    operations = [button("My tasks", "nav:now")]
    if guest_lookup:
        operations.append(button("Find a guest", "nav:guest"))
    keyboard.append(operations)
    if coordinator:
        keyboard.append([button("Coordinator brief", "nav:brief"), button("More details", "nav:details")])
    help_row = [button("Help", "nav:help")]
    if app_url.startswith("https://"):
        help_row.append({"text": "Open LoveOnCue", "web_app": {"url": app_url}})
    keyboard.append(help_row)
    return {"inline_keyboard": keyboard}


def render_brief(brief: dict, *, expanded: bool) -> str:
    urgent, followups, notes = (brief[key] for key in ("urgent", "followups", "notes"))
    lines = ["Coordinator brief", "", f"{len(urgent)} urgent · {len(followups)} follow-ups · {len(notes)} notes"]
    items = [(marker, title, detail)
             for marker, section in [("🔴", urgent), ("🟠", followups), ("•", notes)]
             for title, detail in section]
    limit = 15 if expanded else 6
    if not items:
        lines.extend(["", "No items need attention."])
    size = sum(len(line) + 1 for line in lines)
    shown = 0
    for marker, title, detail in items[:limit]:
        entry = f"{marker} {title[:180]}\n{detail[:240]}"
        # Reserve space for navigation and the availability note.
        if size + len(entry) > 3600:
            break
        lines.extend(["", entry])
        size += len(entry) + 2
        shown += 1
    if expanded and len(items) > shown:
        lines.extend(["", f"{len(items) - shown} more items. Open LoveOnCue to review them."])
    lines.extend(["", "Tap Coordinator brief for the summary." if expanded else "Tap More details for the full list.",
                  "", "Coordinator availability is not recorded. Use an enrolled backup for major decisions."])
    return "\n".join(lines)
